import { ExpoConfig, ConfigContext } from "expo/config"

/**
 * Aaron Rail — Android commute-widget shell.
 *
 * Native projects (android/) are git-ignored and regenerated by `expo prebuild`.
 * The widget timetable is native Kotlin and calls the Better Rail rail API directly.
 *
 * AARON_RAIL_PREVIEW=1 installs a separate app ("Aaron Rail", com.aaronkatzin.rail)
 * next to Play Store Better Rail. android.package stays com.betterrail: Expo uses it
 * as the AGP namespace, and the widget classes live in that package. The preview
 * applicationId is applied later in withAndroidGradle.
 */
const AARON_RAIL_PREVIEW = process.env.AARON_RAIL_PREVIEW === "1"
const ANDROID_PACKAGE = "com.betterrail"

const HEEBO_FONT_ANDROID = {
  fontFamily: "Heebo",
  fontDefinitions: [
    { path: "./assets/fonts/Heebo-Thin.otf", weight: 100 },
    { path: "./assets/fonts/Heebo-Light.otf", weight: 300 },
    { path: "./assets/fonts/Heebo-Regular.otf", weight: 400 },
    { path: "./assets/fonts/Heebo-Medium.otf", weight: 500 },
    { path: "./assets/fonts/Heebo-Bold.otf", weight: 700 },
    { path: "./assets/fonts/Heebo-ExtraBold.otf", weight: 800 },
    { path: "./assets/fonts/Heebo-Black.otf", weight: 900 },
  ],
}

export default ({ config }: ConfigContext): ExpoConfig => ({
  ...config,
  name: AARON_RAIL_PREVIEW ? "Aaron Rail" : "Better Rail",
  slug: "better-rail",
  owner: "better-rail",
  version: "3.0.0",
  orientation: "portrait",
  userInterfaceStyle: "automatic",
  icon: "./assets/icons/android-foreground.png",
  // Preview drops betterrail:// so that scheme stays with the official app.
  scheme: AARON_RAIL_PREVIEW ? ["aaronrail"] : ["betterrail"],
  jsEngine: "hermes",
  assetBundlePatterns: ["**/*"],

  experiments: {
    reactCompiler: true,
  },

  android: {
    package: ANDROID_PACKAGE,
    versionCode: 157,
    allowBackup: false,
    // Widget network calls / local dev.
    usesCleartextTraffic: true,
    adaptiveIcon: {
      foregroundImage: "./assets/icons/android-foreground.png",
      backgroundImage: "./assets/icons/android-background.png",
      monochromeImage: "./assets/icons/android-monochrome.png",
    },
    permissions: ["android.permission.INTERNET", "android.permission.RECEIVE_BOOT_COMPLETED"],
    intentFilters: AARON_RAIL_PREVIEW
      ? [
          {
            action: "VIEW",
            category: ["DEFAULT", "BROWSABLE"],
            data: [{ scheme: "aaronrail" }],
          },
        ]
      : [
          {
            action: "VIEW",
            category: ["DEFAULT", "BROWSABLE"],
            data: [{ scheme: "betterrail" }],
          },
        ],
  },

  plugins: [
    "expo-router",
    // Patched: keeps the app's forceRTL. Built from source on Android so the patch applies.
    "expo-localization",
    "react-native-edge-to-edge",
    [
      "expo-splash-screen",
      {
        backgroundColor: "#f2f2f7",
        dark: {
          backgroundColor: "#1c1c1e",
        },
        android: {
          image: "./assets/icons/android-foreground.png",
          imageWidth: 180,
        },
      },
    ],
    [
      "expo-build-properties",
      {
        android: {
          compileSdkVersion: 37,
          targetSdkVersion: 36,
          minSdkVersion: 24,
          // SDK 58 turns R8 on by default; keep it off until reflection-heavy libs have keep rules.
          enableMinifyInReleaseBuilds: false,
        },
      },
    ],
    ["expo-font", { android: { fonts: [HEEBO_FONT_ANDROID] } }],
    "./plugins/withBetterRailAndroid",
    "@rnrepo/expo-config-plugin",
  ],

  extra: {
    androidPackage: ANDROID_PACKAGE,
  },
})
